using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class RemainingPlacementAudit {static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};public static object Run(){var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("Remaining_Domes_Art");var rows=new[]{"W01","N01"}.SelectMany(code=>root.Find(code).Cast<Transform>().Select(t=>new{room=code,name=t.name,instance=t.GetInstanceID(),position=V(t.localPosition),yaw=t.localEulerAngles.y,colliders=t.GetComponentsInChildren<Collider>().Where(c=>c.enabled).Select(c=>new{c.name,type=c.GetType().Name,center=V(c.bounds.center),size=V(c.bounds.size)})})).ToArray();File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B5_RemainingDomes/placement_audit.json")),JsonConvert.SerializeObject(rows,Formatting.Indented));return rows.Where(r=>r.name.Contains("Desk")||r.name.Contains("Bench")||r.name.Contains("Chair")||r.name.Contains("Archive"));}}
